def find_connected_components_fixed(grid, color=5):
    """Find connected components of color cells."""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = []

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return
        if (r, c) in visited or grid[r][c] != color:
            return
        visited.add((r, c))
        dfs(r+1, c)
        dfs(r-1, c)
        dfs(r, c+1)
        dfs(r, c-1)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and (r, c) not in visited:
                component = set()
                dfs(r, c)
                component = component.copy()
                visited.discard(((r, c),))  # Remove this one out - no wait, this breaks things

                # Better to not modify global visited in dfs
                # Instead, just collect and not mark until end

    # Completely rewritten - BFS style
    visited.clear()
    components = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and (r, c) not in visited:
                component = []
                stack = [(r, c)]
                while stack:
                    curr_r, curr_c = stack.pop()
                    if (curr_r, curr_c) in visited:
                        continue
                    visited.add((curr_r, curr_c))
                    component.append((curr_r, curr_c))
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                stack.append((nr, nc))
                components.append(sorted(component))

    return components

